def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    vals={v for row in grid for v in row}; bg=max(vals,key=lambda v:sum(row.count(v) for row in grid)); fg=next(v for v in vals if v!=bg)
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=fg: continue
            # Pixel switches to 2 if any immediate neighbor in its row/column is another foreground pixel,
            # with only background cells between them. Continue strokes through those gaps.
            for dr,dc in ((0,1),(1,0)):
                rr,cc=r+dr,c+dc
                while rr<h and cc<w and grid[rr][cc]==bg:
                    rr+=dr; cc+=dc
                if rr<h and cc<w and grid[rr][cc]==fg:
                    x,y=r+dr,c+dc
                    while (x,y)!=(rr,cc):
                        out[x][y]=2; x+=dr; y+=dc
    return out
