    # Each isolated foreground pixel in a line is recolored if another foreground pixel
    # is present somewhere else in the same row/column, but the marked color is the gaps.
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    vals={v for row in grid for v in row}; bg=max(vals,key=lambda v:sum(row.count(v) for row in grid)); fg=next(v for v in vals if v!=bg)
    for r in range(h):
        ps=[c for c in range(w) if grid[r][c]==fg]
        for a,b in zip(ps,ps[1:]):
            for c in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=2
    for c in range(w):
        ps=[r for r in range(h) if grid[r][c]==fg]
        for a,b in zip(ps,ps[1:]):
            for r in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=2
    return out
