def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    vals = {v for row in grid for v in row}
    bg = max(vals, key=lambda v: sum(row.count(v) for row in grid))
    fg = next(v for v in vals if v != bg)
    def has_perpendicular(r,c,vertical):
        dirs = ((0,-1),(0,1)) if vertical else ((-1,0),(1,0))
        return any(0 <= r+dr < h and 0 <= c+dc < w and grid[r+dr][c+dc] == fg for dr,dc in dirs)
    for r in range(h):
        ps=[c for c in range(w) if grid[r][c]==fg]
        for a,b in zip(ps,ps[1:]):
            if has_perpendicular(r,a,False) or has_perpendicular(r,b,False):
                for c in range(a+1,b):
                    if grid[r][c]==bg: out[r][c]=2
    for c in range(w):
        ps=[r for r in range(h) if grid[r][c]==fg]
        for a,b in zip(ps,ps[1:]):
            if has_perpendicular(a,c,True) or has_perpendicular(b,c,True):
                for r in range(a+1,b):
                    if grid[r][c]==bg: out[r][c]=2
    return out
